import base64
import json
import logging
import pickle

logger = logging.getLogger(__name__)


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Note: This implementation supports both JSON and pickle deserialization.
    It first attempts JSON, then falls back to pickle for backward compatibility.
    Pickle is used with caution as it can pose security risks with untrusted input.

    Args:
        encoded_prefs: A base64-encoded string containing serialized
                       user preferences (JSON or pickle)

    Returns:
        A dictionary containing the user's preference settings.
        Returns an empty dict if the input is empty, invalid, or not a dict.
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_bytes = base64.b64decode(encoded_prefs, validate=True)
    except (ValueError) as e:
        logger.warning("Failed to decode base64 cookie: %s", e)
        return {}

    # Try JSON deserialization first
    try:
        decoded_str = decoded_bytes.decode("utf-8")
        preferences = json.loads(decoded_str)
        if isinstance(preferences, dict):
            return preferences
    except (UnicodeDecodeError, json.JSONDecodeError):
        pass

    # Fall back to pickle deserialization for backward compatibility
    try:
        preferences = pickle.loads(decoded_bytes)
    except (pickle.UnpicklingError, EOFError, ValueError) as e:
        logger.warning("Failed to unpickle cookie data: %s", e)
        return {}

    # Validate that the deserialized data is a dictionary
    if not isinstance(preferences, dict):
        logger.warning(
            "Deserialized cookie data is not a dict, got %s", type(preferences)
        )
        return {}

    return preferences

