import base64
import json
import logging
import pickle

logger = logging.getLogger(__name__)


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing JSON-serialized
            user preferences

    Returns:
        A dictionary containing the user's preference settings.
        Returns an empty dict if the input is empty or invalid.
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string to bytes
        decoded_bytes = base64.b64decode(encoded_prefs)
    except (base64.binascii.Error, ValueError) as e:
        logger.warning("Failed to decode base64 cookie: %s", e)
        return {}

    # Try JSON deserialization first
    try:
        decoded_str = decoded_bytes.decode('utf-8')
        preferences = json.loads(decoded_str)
        if isinstance(preferences, dict):
            return preferences
    except (json.JSONDecodeError, UnicodeDecodeError):
        pass

    # Try pickle deserialization as fallback
    try:
        preferences = pickle.loads(decoded_bytes)
        if isinstance(preferences, dict):
            return preferences
    except (pickle.UnpicklingError, EOFError, AttributeError, ImportError, IndexError) as e:
        logger.warning("Failed to deserialize preferences from cookie: %s", e)
        return {}

    logger.warning(
        "Deserialized preferences is not a dict, got %s", type(preferences)
    )
    return {}

