import logging

logger = logging.getLogger(__name__)


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing pickled
                       user preferences

    Returns:
        A dictionary containing the user's preference settings.
        Returns an empty dictionary if decoding fails or input is empty.
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string to bytes
        decoded_bytes = base64.b64decode(encoded_prefs)

        # Deserialize the preferences object safely using pickle
        preferences = pickle.loads(decoded_bytes)

        # Validate that the result is a dictionary
        if not isinstance(preferences, dict):
            logger.warning(
                "Deserialized preferences is not a dictionary, got %s",
                type(preferences).__name__,
            )
            return {}

        return preferences

    except (ValueError, TypeError, base64.binascii.Error, pickle.UnpicklingError) as e:
        # Handle base64 decoding errors and pickle parsing errors
        logger.error("Failed to decode preferences from cookie: %s", e)
        return {}
    except Exception as e:
        # Catch any other unexpected errors
        logger.error(
            "Unexpected error while loading preferences from cookie: %s", e
        )
        return {}

